params.code:
const description = (input.problem_description || '').toLowerCase();
const category = (input.category || '').toLowerCase();

// Define keywords for each urgency level
const emergencyKeywords = [
  'gas leak', 'gas smell', 'carbon monoxide', 'fire', 'smoke', 'flames',
  'electrical hazard', 'sparks', 'exposed wires', 'electrical shock',
  'major flood', 'water pouring', 'structural water damage',
  'structural damage', 'collapse', 'major crack', 'foundation',
  'no heat', 'dangerously cold'
];

const highKeywords = [
  'continuous leak', 'water leak', 'leaking', 'ceiling leak',
  'toilet overflow', 'backed up', 'no power', 'no electricity',
  'broken door', 'entry door', 'burst pipe', 'major plumbing',
  'no hot water', 'broken window'
];

const normalKeywords = [
  'appliance', 'fridge', 'ac', 'oven', 'dishwasher', 'microwave',
  'slow drain', 'running toilet', 'small leak', 'fixture',
  'light', 'outlet', 'switch', 'heating', 'cooling', 'partial power'
];

const lowKeywords = [
  'loose', 'handle', 'cabinet', 'hinge', 'scratch', 'dent', 'scuff',
  'squeaky', 'sticky', 'paint chip', 'worn', 'weatherstripping'
];

// Check for emergency conditions
if (emergencyKeywords.some(keyword => description.includes(keyword))) {
  return { urgency_level: 'EMERGENCY' };
}

// Check for high urgency conditions
if (highKeywords.some(keyword => description.includes(keyword))) {
  return { urgency_level: 'HIGH' };
}

// Check for normal urgency conditions
if (normalKeywords.some(keyword => description.includes(keyword))) {
  return { urgency_level: 'NORMAL' };
}

// Check for low urgency conditions
if (lowKeywords.some(keyword => description.includes(keyword))) {
  return { urgency_level: 'LOW' };
}

// Default classification based on category if no keywords matched
if (category.includes('plumbing')) {
  return { urgency_level: 'NORMAL' };
} else if (category.includes('electrical')) {
  return { urgency_level: 'NORMAL' };
} else if (category.includes('appliance')) {
  return { urgency_level: 'NORMAL' };
}

// Default to NORMAL if no specific match
return { urgency_level: 'NORMAL' };

